package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class JsonParserSequence_nextToken_TriageGen1Test {

    /**
     * Since JsonParserSequence has a protected constructor and the method being tested 
     * relies on protected/internal logic (switchToNext), we use a subclass to expose 
     * the protected behavior or mock the parser array.
     */
    private static class TestableJsonParserSequence extends JsonParserSequence {
        private final JsonParser[] parsers;
        private int currentParserIndex = 0;

        protected TestableJsonParserSequence(JsonParser[] parsers) {
            super(parsers);
            this.parsers = parsers;
        }

        @Override
        protected boolean switchToNext() {
            if (currentParserIndex < parsers.length - 1) {
                currentParserIndex++;
                return true;
            }
            return false;
        }
    }

    @Test
    public void testNextToken_FirstParserReturnsToken() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(parser1, times(1)).nextToken();
        verify(parser2, never()).nextToken();
    }

    @Test
    public void testNextToken_FirstParserNullThenSecondParserReturnsToken() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(parser1, times(1)).nextToken();
        verify(parser2, times(1)).nextToken();
    }

    @Test
    public void testNextToken_AllParsersReturnNull() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(null);

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});

        JsonToken result = sequence.nextToken();

        assertNull(result);
        verify(parser1, times(1)).nextToken();
        verify(parser2, times(1)).nextToken();
    }

    @Test
    public void testNextToken_SingleParserNull() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        when(parser1.nextToken()).thenReturn(null);

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1});

        JsonToken result = sequence.nextToken();

        assertNull(result);
        verify(parser1, times(1)).nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_ThrowsIOException() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        when(parser1.nextToken()).thenThrow(new IOException("Simulated error"));

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1});

        sequence.nextToken();
    }

    @Test(expected = JsonParseException.class)
    public void testNextToken_ThrowsJsonParseException() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        when(parser1.nextToken()).thenThrow(new JsonParseException(null, "Parse error"));

        JsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1});

        sequence.nextToken();
    }
}
